+import { z } from 'zod';
+import { CARRIERS, SERVICE_LEVELS, type Carrier, type ServiceLevel } from '../types.ts';
+import { checkAtpTrackingNumber } from './s10.ts';
+
+// Keep this file free of server-only imports (HttpError etc.) so the schemas can be shared with the mobile app.
+
+/** Issue params used to carry the API error code through zod. */
+export const ERROR_CODE_PARAM = 'apiCode';
+
+const requiredString = (label: string) =>
+  z.string({ error: `${label} is required` }).trim().min(1, `${label} is required`);
+
+const optionalTrimmed = z
+  .unknown()
+  .optional()
+  .transform((v) => (typeof v === 'string' && v.trim() !== '' ? v.trim() : undefined));
+
+const recipientSchema = z.object(
+  {
+    name: requiredString('recipient.name'),
+    street: requiredString('recipient.street'),
+    zip: requiredString('recipient.zip'),
+    city: requiredString('recipient.city'),
+    country: optionalTrimmed.transform((v) => (v ?? 'AT').toUpperCase()),
+    phone: optionalTrimmed,
+  },
+  { error: 'recipient is required' },
+).transform(({ phone, ...rest }) => ({ ...rest, ...(phone !== undefined ? { phone } : {}) }));
+
+export const shipmentInputSchema = z
+  .object(
+    {
+      tracking_number: requiredString('tracking_number').transform((v) => v.toUpperCase()),
+      carrier: requiredString('carrier')
+        .transform((v) => v.toUpperCase())
+        .refine((v): v is Carrier => (CARRIERS as readonly string[]).includes(v), {
+          error: `carrier must be one of ${CARRIERS.join(', ')}`,
+        }),
+      service_level: z
+        .unknown()
+        .optional()
+        .transform((v) => v ?? 'standard')
+        .refine((v): v is ServiceLevel => typeof v === 'string' && (SERVICE_LEVELS as readonly string[]).includes(v), {
+          error: `service_level must be one of ${SERVICE_LEVELS.join(', ')}`,
+        }),
+      recipient: recipientSchema,
+    },
+    { error: 'body must be a JSON object' },
+  )
+  .superRefine((body, ctx) => {
+    // Only ATP numbers are validated. Other carriers' formats change too often (valid DHL numbers
+    // were rejected for two days in 2025), so any non-empty value is accepted for them.
+    if (body.carrier !== 'ATP') return;
+    const check = checkAtpTrackingNumber(body.tracking_number);
+    if (check === 'bad_format') {
+      ctx.addIssue({
+        code: 'custom',
+        path: ['tracking_number'],
+        params: { [ERROR_CODE_PARAM]: 'INVALID_TRACKING_NUMBER' },
+        message:
+          'Ungültige Sendungsnummer für ATP: erwartet wird das Format S10, z. B. RR123456785AT (2 Buchstaben, 8 Ziffern, 1 Prüfziffer, AT)',
+      });
+    } else if (check === 'bad_check_digit') {
+      ctx.addIssue({
+        code: 'custom',
+        path: ['tracking_number'],
+        params: { [ERROR_CODE_PARAM]: 'INVALID_TRACKING_NUMBER_CHECK_DIGIT' },
+        message: 'Ungültige Sendungsnummer für ATP: Die Prüfziffer stimmt nicht. Bitte die Nummer auf dem Etikett prüfen',
+      });
+    }
+  });
+
+export type ShipmentBody = z.output<typeof shipmentInputSchema>;
