+import assert from 'node:assert/strict';
+import { describe, it } from 'node:test';
+import { shipmentInputSchema } from '../src/lib/schemas.ts';
+import { validateShipmentInput } from '../src/lib/validate.ts';
+
+const base = () => ({
+  tracking_number: ' rr123456785at ',
+  carrier: 'atp',
+  recipient: { name: ' Anna ', street: 'Ring 1', zip: '1010', city: 'Wien', phone: '  ' },
+});
+
+function fails(body: unknown) {
+  try {
+    validateShipmentInput(body);
+  } catch (e: any) {
+    return e as { status: number; code: string; message: string };
+  }
+  assert.fail('expected validation to fail');
+}
+
+describe('shipmentInputSchema', () => {
+  it('normalizes input and applies defaults', () => {
+    const out = shipmentInputSchema.parse(base());
+    assert.equal(out.tracking_number, 'RR123456785AT');
+    assert.equal(out.carrier, 'ATP');
+    assert.equal(out.service_level, 'standard');
+    assert.deepEqual(out.recipient, { name: 'Anna', street: 'Ring 1', zip: '1010', city: 'Wien', country: 'AT' });
+  });
+
+  it('keeps a trimmed phone and upper-cases the country', () => {
+    const out = validateShipmentInput({ ...base(), recipient: { ...base().recipient, phone: ' +43 1 ', country: 'de' } });
+    assert.equal(out.recipient.phone, '+43 1');
+    assert.equal(out.recipient.country, 'DE');
+  });
+
+  it('keeps the existing error responses', () => {
+    assert.deepEqual(
+      [fails(null).code, fails(null).message],
+      ['VALIDATION_FAILED', 'body must be a JSON object'],
+    );
+    assert.equal(fails({ ...base(), tracking_number: '  ' }).message, 'tracking_number is required');
+    assert.match(fails({ ...base(), carrier: 'FEDEX' }).message, /^carrier must be one of ATP, DHL/);
+    assert.match(fails({ ...base(), service_level: 'turbo' }).message, /^service_level must be one of/);
+    assert.equal(fails({ ...base(), recipient: undefined }).message, 'recipient is required');
+    assert.equal(fails({ ...base(), recipient: { ...base().recipient, zip: '' } }).message, 'recipient.zip is required');
+  });
+
+  it('keeps the ATP tracking number error codes', () => {
+    assert.equal(fails({ ...base(), tracking_number: 'nonsense' }).code, 'INVALID_TRACKING_NUMBER');
+    assert.equal(fails({ ...base(), tracking_number: 'RR123456786AT' }).code, 'INVALID_TRACKING_NUMBER_CHECK_DIGIT');
+    assert.equal(fails({ ...base(), tracking_number: 'RR123456786AT' }).status, 400);
+  });
+
+  it('does not validate the tracking number format for other carriers', () => {
+    assert.equal(validateShipmentInput({ ...base(), carrier: 'DHL', tracking_number: 'abc' }).trackingNumber, 'ABC');
+  });
+});
